'use strict';
let p1=new Fighter(W*.27,roster[0],0),p2=new Fighter(W*.73,roster[1],1),usedHits=new Set();
async function startFight(){initAudio();await tryLandscapeLock();showScreen('#mainMenu');$$('.screen').forEach(s=>s.classList.add('hidden'));p1=new Fighter(W*.27,roster[picks[0]],0);p2=new Fighter(W*.73,roster[picks[1]],1);round=1;timer=mode==='training'?999:60;roundWins=[0,0];ending=false;running=true;paused=false;wrap.classList.add('playing');particles=[];projectiles=[];trails=[];usedHits.clear();$('#p1Name').textContent=p1.data.name;$('#p2Name').textContent=p2.data.name;$('#p2tag').textContent=mode==='pvp'?'PLAYER 2':mode==='training'?'DUMMY':'CPU';$('#roundText').textContent=mode==='training'?'TRAINING':'ROUND 1';renderDots();buildMeters();updateHud();showBanner(mode==='training'?'TRAINING':'ROUND 1','',650);setTimeout(()=>showBanner('FIGHT!','M1 + M2 = ROUTES',620),650)}
function buildMeters(){for(const id of ['#p1meter','#p2meter']){$(id).innerHTML='';for(let i=0;i<3;i++){const s=document.createElement('div');s.className='meterSeg';$(id).appendChild(s)}}}
function controlP1(){return {left:keys.a||touch.left,right:keys.d||touch.right,jump:edge('w')||edgeTouch('jump'),block:keys.s||touch.block,m1:edge('j')||edgeTouch('m1'),m2:edge('k')||edgeTouch('m2'),special:edge('l')||edgeTouch('special'),super:edge(' ')||edgeTouch('super'),dash:edge('shift')||edgeTouch('dash')}}
function controlP2(){return {left:keys.arrowleft,right:keys.arrowright,jump:edge('arrowup'),block:keys.arrowdown,m1:edge('u'),m2:edge('i'),special:edge('o'),super:edge('p'),dash:edge('0')}}
const prevKeys={},prevTouch={};function edge(k){return !!keys[k]&&!prevKeys[k]}function edgeTouch(k){return !!touch[k]&&!prevTouch[k]}
function saveEdges(){for(const k in keys)prevKeys[k]=keys[k];for(const k in touch)prevTouch[k]=touch[k]}
addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if(k==='escape'&&running)togglePause();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault()},{passive:false});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
$$('.ctrl').forEach(b=>{const k=b.dataset.key;const on=e=>{e.preventDefault();touch[k]=true;b.classList.add('active')},off=e=>{e.preventDefault();touch[k]=false;b.classList.remove('active')};b.addEventListener('pointerdown',on);b.addEventListener('pointerup',off);b.addEventListener('pointercancel',off);b.addEventListener('pointerleave',off)});
